// Erste No-Show: freundliche Nachricht
const d = $input.first().json;
const noShowCount = d.no_show_count;

let message = '';

if (noShowCount === 1) {
  message = `Hallo ${d.client_name} 😊

Wir haben dich heute leider vergeblich erwartet. Kein Problem – das kann passieren!

Möchtest du einen neuen Termin buchen? Wir freuen uns auf dich! 💇

Dein Team von ${d.salon_name}`;
} else if (noShowCount === 2) {
  message = `Hallo ${d.client_name},

du hast heute leider zum zweiten Mal deinen Termin nicht wahrgenommen.

Wir bitten um Verständnis, dass wir bei der nächsten Buchung eine Anzahlung erheben müssen. So können wir unsere Plätze fair an alle Kunden vergeben.

Neuen Termin buchen? Einfach hier antworten! 😊

Dein Team von ${d.salon_name}`;
} else {
  message = `Hallo ${d.client_name},

leider konntest du deinen Termin erneut nicht wahrnehmen.

Für zukünftige Buchungen ist eine Vorab-Anzahlung erforderlich. Du kannst ganz einfach online buchen und bezahlen.

Bei Fragen erreichst du uns jederzeit.

Dein Team von ${d.salon_name}`;
}

return [{
  json: {
    ...d,
    message,
    severity: noShowCount >= 3 ? 'high' : noShowCount === 2 ? 'medium' : 'low'
  }
}];
